class Solution {
    public int lengthOfLIS(int[] nums) {
        return search(nums, 0, -1);
    }

    private int search(int[] nums, int index, int previousIndex) {
        if (index == nums.length) return 0;
        int best = search(nums, index + 1, previousIndex);
        if (previousIndex == -1 || nums[index] > nums[previousIndex]) {
            best = Math.max(best, 1 + search(nums, index + 1, index));
        }
        return best;
    }
}

